<?php $rows = $rows ?? []; $labelHeading = $labelHeading ?? 'Name'; $showPatients = $showPatients ?? false; ?>
<div class="table-responsive"><table class="table table-sm table-hover align-middle mb-0"><thead><tr><th><?= esc($labelHeading) ?></th><?php if ($showPatients) : ?><th class="text-end">Patients</th><?php endif ?><th class="text-end">Cases</th></tr></thead><tbody><?php if (empty($rows)) : ?><tr><td colspan="<?= $showPatients ? 3 : 2 ?>" class="dashboard-empty">No data in this period.</td></tr><?php else : ?><?php foreach ($rows as $row) : ?><tr><td><?= esc($row['label'] ?? 'Unassigned') ?></td><?php if ($showPatients) : ?><td class="text-end"><?= (int) ($row['patients'] ?? 0) ?></td><?php endif ?><td class="text-end fw-semibold"><?= (int) ($row['total'] ?? 0) ?></td></tr><?php endforeach ?><?php endif ?></tbody></table></div>